import { modelPicker, modelLabel } from './lib/models.js';
import { researchDetails } from './lib/research-report.js';
import { allRequests, saveRequest, removeRequest, createRequest } from './lib/store.js';
import { renderLive, mountLive, mountRuntime } from './lib/live.js';
import { STATUS, SAMPLE_ID, SAMPLE_REPORT, sampleRequest, newId, escapeHTML as h, safeURL, imageURL, referenceURL, modeLabel, normalizeReport, validatePublication, reportTemplate, handoffText, restoreRequest, zipBytes } from './lib/domain.js';

const paths = {
  frame:'M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5M10 12h4m-2-2v4',
  arrow:'M4 12h15m-6-6 6 6-6 6',upRight:'M6 18 18 6M6 6h12v12',
  pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',
  camera:'M8 5 10 3h4l2 2h5v15H3V5h5Z M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',
  search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',
  upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6', download:'M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5',
  image:'M3 3h18v18H3z M3 17l6-6 4 4 3-3 5 5M8 7h.01',
  check:'m5 12 4 4L19 6',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',
  layers:'m12 3 10 6-10 6L2 9l10-6ZM2 14l10 6 10-6',
  copy:'M8 8h13v13H8zM16 8V3H3v13h5',plus:'M12 5v14M5 12h14',
  info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',
  chevron:'m9 5 7 7-7 7',close:'m6 6 12 12M6 18 18 6',
  file:'M14 2H5v20h14V7l-5-5Zm0 0v6h5M8 13h8m-8 4h6',
  folder:'M3 5h7l2 2h9v14H3V5Z',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',
  sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5M17.5 17.5 19 19M5 19l1.5-1.5M17.5 6.5 19 5M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0Z',
  compass:'m16 8-3 5-5 3 3-5 5-3ZM22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',
  walk:'m10 10 3 3 4 1M8 21l3-7m2 7-1-5-4-4 2-5h4l2 4m-2-7h.01',
  print:'M6 9V3h12v6M6 18H3V9h18v9h-3M6 14h12v8H6zM17 11h.01',
  trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',
  mail:'M3 5h18v14H3V5Zm0 0 9 8 9-8',edit:'m15 4 5 5-11 11-6 1 1-6L15 4Z',
};
function icon(name,cls=''){return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.frame}"/></svg>`;}
const main=document.querySelector('#main');
let requests=[],pendingReference=null,filter='all',studioTab='brief',editingId=null,editorReport=null,currentRoute='',creating=false;
let disposeLive=null;
const json=(v)=>JSON.stringify(v,null,2);
const dateText=(d)=>new Intl.DateTimeFormat('ko-KR',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'Asia/Seoul'}).format(new Date(d));
const badge=(status)=>`<span class="badge ${status}">${STATUS[status]?.label||h(status)}</span>`;
const img=(url,alt,cls='',extra='')=>imageURL(url)?`<img class="${cls}" src="${h(imageURL(url))}" alt="${h(alt)}" ${extra}>`:`<div class="no-image ${cls}">${icon('image')}</div>`;
const sampleTag=(r)=>r.isSample?'<span class="sample-tag">SAMPLE</span>':'';
const statusCount=(s)=>requests.filter(r=>!r.isSample&&r.status===s).length;
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=icon(error?'info':'check')+`<span>${h(message)}</span>`;document.querySelector('#toasts').append(el);setTimeout(()=>el.remove(),4800);}
function go(path){location.hash=path;}
function brand(){return `<a class="brand" href="#/" aria-label="FRAME 홈"><span class="brand-mark">${icon('frame')}</span>FRAME<small>LOCATION<br>RESEARCH</small></a>`;}
function chrome(path){
  document.querySelector('#header').innerHTML=`<nav class="nav container" aria-label="주 메뉴">${brand()}<div class="nav-links"><a href="#/new" class="${path.startsWith('/new')?'active':''}">리서치 의뢰</a><a href="#/requests" class="${path.startsWith('/requests')||path.startsWith('/report')||path.startsWith('/live')?'active':''}">내 리서치${requests.filter(r=>!r.isSample).length?`<span class="nav-count">${requests.filter(r=>!r.isSample).length}</span>`:''}</a><a class="sample-nav ${path.includes(SAMPLE_ID)&&!path.startsWith('/studio')?'active':''}" href="#/report/${SAMPLE_ID}">샘플 리포트</a><span class="nav-separator"></span><a class="studio-link ${path.startsWith('/studio')?'active':''}" href="#/studio">스튜디오 ${icon('upRight')}</a></div></nav>`;
  document.querySelector('#footer').innerHTML=`<div class="footer container"><div class="row">${brand()}<span>사진에서 시작되는 다음 장면.</span></div><div class="footer-links"><p>LOCAL EDITION · 이 PC에 저장됩니다.</p><a href="#/studio">운영자 스튜디오 ${icon('upRight')}</a></div></div>`;
}
function renderHome(){
  return `<div class="container home"><section class="hero" aria-label="FRAME 소개"><img class="hero-photo" src="./assets/lake.jpg" alt="맑은 호수 너머로 겹쳐 보이는 알프스의 산 능선"><div class="hero-content"><div class="eyebrow"><span class="dot"></span> FROM A FRAME, TO A PLACE.</div><h1>사진 속 그곳,<br>당신의 다음<br><em>촬영지가 되도록.</em></h1><p>마음에 담아 둔 사진 한 장을 보내 주세요.<br>장소부터 카메라 방향, 확인 근거까지 함께 찾아갑니다.</p><div class="hero-actions"><a class="btn btn-lime" href="#/new">나의 촬영지 찾기 ${icon('arrow')}</a><a class="text-link" href="#/report/${SAMPLE_ID}">완성된 리포트 둘러보기 ${icon('upRight')}</a></div></div><span class="hero-cross">＋</span><div class="hero-pin"><span class="hero-pin-point"></span><div class="hero-pin-label">장면을 이루는 단서들<small>RIDGELINE · WATERFRONT</small></div></div><div class="hero-corner"><div><span>REFERENCE 001</span>THE LAKESIDE FRAME</div><div><span>VISUAL SAMPLE</span>DOLOMITES / ITALY</div></div></section><div class="hero-footer"><span>${icon('compass')} 감으로 고른 장소에, 확인 가능한 근거를.</span><div class="steps-inline"><span><b>01</b> 사진과 요청 전달</span><span><b>02</b> 단서를 따라 리서치</span><span><b>03</b> 촬영지 카드 완성</span></div></div><section aria-label="리서치 시작하기"><div class="section-head"><div><div class="eyebrow">EVERY FRAME HAS A PLACE</div><h2>어떤 장면을 찾고 있나요?</h2><p>레퍼런스에서 시작해, 실제 촬영을 위한 한 걸음까지.</p></div><a href="#/new">리서치 시작하기 ${icon('arrow')}</a></div><div class="spot-grid"><button class="spot-card" data-action="sample-report"><div class="spot-image"><img src="./assets/lake.jpg" alt="산과 호수가 어우러진 풍경" loading="lazy"><span class="sample-tag">SAMPLE REPORT</span></div><div class="spot-content"><small>FIND THE ORIGINAL</small><h3>호수와 능선이 겹치는 프레임</h3><div><span>장소 · 촬영 방향 · 근거 보기</span>${icon('upRight')}</div></div></button><button class="spot-card" data-action="sample-new" data-kind="coast"><div class="spot-image"><img src="./assets/coast.jpg" alt="빛을 받아 부서지는 바다의 파도" loading="lazy"><span class="sample-tag">REFERENCE IDEA</span></div><div class="spot-content"><small>FIND YOUR NEXT SCENE</small><h3>파도를 마주하는 나만의 자리</h3><div><span>비슷한 촬영지 의뢰하기</span>${icon('upRight')}</div></div></button><button class="spot-card" data-action="sample-new" data-kind="mountain"><div class="spot-image"><img src="./assets/mountain.jpg" alt="구름 사이로 드러난 높은 산의 능선" loading="lazy"><span class="sample-tag">REFERENCE IDEA</span></div><div class="spot-content"><small>FOLLOW THE CLUES</small><h3>이 능선은 어디서 보일까요?</h3><div><span>사진 속 촬영지 의뢰하기</span>${icon('upRight')}</div></div></button></div></section><section class="manifesto" aria-label="서비스 진행 방식"><div><div class="number">01.</div><h3>장면을 보내 주세요</h3><p>사진 한 장과 찾고 싶은 장면을 알려 주세요.<br>원래 촬영지도, 비슷한 구도의 장소도 좋습니다.</p></div><div><div class="number">02.</div><h3>작은 단서까지 확인합니다</h3><p>산 능선, 건물의 배치, 거리의 모양.<br>사진과 지도에서 맞아떨어지는 근거를 찾습니다.</p></div><div><div class="number">03.</div><h3>다음 촬영을 준비하세요</h3><p>위치와 방향, 비교 이미지가 담긴 리포트.<br>확인된 것과 더 확인할 것을 함께 전달합니다.</p></div></section></div>`;
}
function uploadMarkup(){
  const r=pendingReference;return `<div id="upload-zone" class="upload-box ${r?'has-image':''}" tabindex="0" role="button" aria-label="레퍼런스 사진 업로드">${r?`${img(r.dataUrl||r.url,'업로드한 레퍼런스 사진')}<div class="upload-meta">${icon('image')}<span>${h(r.name)}</span><button type="button" data-action="replace-image">사진 변경</button><button type="button" data-action="remove-reference" aria-label="레퍼런스 삭제">✕</button></div>`:`<div class="upload-inner"><span class="upload-icon">${icon('image')}</span><strong>레퍼런스 사진을 놓아 주세요</strong><p>또는 파일을 선택해 업로드하세요</p><span class="btn btn-outline btn-small">${icon('plus')} 사진 선택</span><p style="margin:14px 0 0;font-size:10px">JPG · PNG · WEBP / 최대 20MB</p></div>`}</div><input type="file" id="reference-file" accept="image/jpeg,image/png,image/webp" hidden>`;
}
function renderNew(){
  return `<div class="container"><div class="page-top"><div class="breadcrumb"><a href="#/">홈</a>${icon('chevron')}<span>리서치 의뢰</span></div></div><div class="create-grid"><aside class="create-aside"><div class="eyebrow"><span class="dot"></span> START WITH A FRAME</div><h1>어떤 장면을<br>찾고 있나요?</h1><p>한 장의 사진에서 시작하는 로케이션 리서치.<br>마음에 그린 장면을 함께 구체화해 봅니다.</p><div id="upload-area">${uploadMarkup()}</div><div class="aside-note">${icon('info')}<span>분석할 권한이 있는 사진을 올려 주세요.<br>원본 파일은 변환하지 않고 조사 패키지에 담습니다.</span></div><div class="use-sample"><span>먼저 흐름을 경험해 보고 싶다면</span><button data-action="sample-reference">샘플 사진 사용 ${icon('arrow')}</button></div></aside><form id="request-form" class="form-card"><div id="request-error" role="alert"></div><div id="runtime-check" class="runtime-card"><p>로컬 조사 환경을 확인하고 있습니다.</p></div>${modelPicker()}<section class="form-section"><div class="form-section-heading"><span>01</span><h2>어떤 리서치가 필요한가요?</h2></div><div class="choice-grid"><label class="choice"><input type="radio" name="mode" value="original" checked>${icon('pin')}<strong>사진 속 촬영지 찾기</strong><small>사진이 촬영된 장소와<br>카메라 위치·방향을 찾습니다.</small></label><label class="choice"><input type="radio" name="mode" value="alternative">${icon('layers')}<strong>비슷한 촬영지 찾기</strong><small>원하는 지역 안에서<br>비슷한 장면의 후보를 찾습니다.</small></label></div></section><section class="form-section"><div class="form-section-heading"><span>02</span><h2>촬영 계획을 알려 주세요</h2></div><label class="field"><span>프로젝트 이름 <em>*</em></span><input name="title" maxlength="100" placeholder="예: 가을 캠페인, 물가의 조용한 장면" required></label><div class="field-grid"><label class="field"><span>찾을 지역 <small>선택</small></span><input name="region" maxlength="120" placeholder="예: 제주, 서울 근교 / 미입력 시 제한 없음"></label><label class="field"><span>촬영 예정일 <small>선택</small></span><input name="date" type="date" aria-label="촬영 예정일"></label></div><div class="field"><span>촬영 목적</span><div class="chip-select"><label class="chip"><input name="purpose" type="radio" value="사진 촬영" checked>사진 촬영</label><label class="chip"><input name="purpose" type="radio" value="영상 촬영">영상 촬영</label><label class="chip"><input name="purpose" type="radio" value="답사·여행">답사·여행</label><label class="chip"><input name="purpose" type="radio" value="기타">기타</label></div></div></section><section class="form-section"><div class="form-section-heading"><span>03</span><h2>어떤 점을 확인할까요?</h2></div><label class="field"><span>리서치 요청사항 <em>*</em></span><textarea name="brief" maxlength="5000" placeholder="예: 사진처럼 호수와 산이 함께 보이는 곳을 찾고 싶어요. 카메라가 서 있었던 위치와 방향을 알려 주세요." required></textarea></label><label class="field"><span>추가 조건 <small>선택</small></span><input name="constraints" maxlength="500" placeholder="예: 대중교통 접근, 일출 방향, 차량 1시간 이내"></label></section><div class="form-bottom"><button class="btn btn-primary btn-block" type="submit">리서치 시작하기 ${icon('arrow')}</button><p>사진을 보내면 바로 조사를 시작합니다. 다음 화면에서 실시간으로 확인하세요.</p></div></form></div></div>`;
}
function renderRequests(){
  const shown=requests.filter(r=>filter==='all'||r.status===filter);
  return `<div class="container"><div class="page-top"><div class="breadcrumb"><a href="#/">홈</a>${icon('chevron')}<span>내 리서치</span></div><div class="request-head"><div><div class="eyebrow">YOUR LOCATION JOURNAL</div><h1>나의 다음 장면들</h1><p>의뢰한 리서치와 완성된 촬영지 리포트를 한곳에서.</p></div><div class="row"><button class="btn btn-outline btn-small" data-action="restore-backup">${icon('upload')} 의뢰 가져오기</button><a class="btn btn-primary" href="#/new">${icon('plus')} 새 리서치</a></div></div></div><div class="tabs" role="tablist" aria-label="진행 상태 필터">${[['all','전체'],['received','접수 완료'],['researching','리서치 중'],['ready','완성'],['review','확인 필요'],['failed','실행 확인'],['cancelled','중지'],['interrupted','중단']].map(([key,label])=>`<button role="tab" aria-selected="${filter===key}" class="${filter===key?'active':''}" data-action="filter" data-value="${key}">${label}<span>${key==='all'?requests.length:requests.filter(r=>r.status===key).length}</span></button>`).join('')}</div><div class="requests-layout"><div><div class="request-list">${shown.length?shown.map(r=>`<article class="request-card">${img(referenceURL(r),r.title,'request-thumb',`data-action="open-request" data-id="${h(r.id)}"`)}<div class="request-info"><div class="row">${badge(r.status)}${sampleTag(r)}</div><h3><a href="#/report/${h(r.id)}">${h(r.title)}</a></h3><div class="request-meta"><span>${modeLabel(r.mode)}</span><span>${h(r.region||'지역 제한 없음')}</span><span>${dateText(r.createdAt)}</span></div><div class="request-actions"><a href="#/report/${h(r.id)}">${r.report?'리포트 보기':'진행 상태 보기'} ${icon('arrow')}</a><span class="spacer"></span><button data-action="export-backup" data-id="${h(r.id)}">${icon('download')} 백업</button>${!r.isSample?`<button data-action="delete-request" data-id="${h(r.id)}" aria-label="${h(r.title)} 의뢰 삭제">${icon('trash')}</button>`:''}</div></div></article>`).join(''):`<div class="empty-state">${icon('folder')}<h3>이 상태의 리서치가 없습니다</h3><p>새로운 장면을 찾는 리서치를 시작해 보세요.</p><a class="btn btn-primary" href="#/new">새 리서치 의뢰 ${icon('arrow')}</a></div>`}</div><div class="storage-note" style="margin-top:20px">${icon('info')}<span>사진·의뢰·조사 기록은 이 PC의 로컬 서버에 저장됩니다. 진행 중인 의뢰를 열면 실시간 조사 과정을 볼 수 있습니다.</span></div></div><aside class="help-card"><h3>이렇게 진행됩니다</h3><div class="process-vertical"><div class="process-step"><span class="step-num">1</span><div><h4>의뢰 접수</h4><p>사진과 촬영 조건을 확인합니다.</p></div></div><div class="process-step"><span class="step-num">2</span><div><h4>단서 조사와 대조</h4><p>장소 후보와 확인 가능한<br>근거를 비교합니다.</p></div></div><div class="process-step"><span class="step-num">3</span><div><h4>촬영지 리포트 전달</h4><p>위치·방향·근거와<br>남은 확인사항을 전달합니다.</p></div></div></div><div class="line"></div><a href="#/report/${SAMPLE_ID}">샘플 리포트 둘러보기 ${icon('upRight')}</a></aside></div><input type="file" id="backup-file" accept="application/json,.json" hidden></div>`;
}
function renderSubmitted(r){return `<div class="container"><section class="submitted"><div class="success-icon">${icon('check')}</div><div class="eyebrow" style="justify-content:center;margin-bottom:14px">YOUR NEXT FRAME STARTS HERE</div><h1>리서치 의뢰가 준비되었습니다.</h1><p>사진 속 작은 단서에서 다음 촬영지까지.<br>운영자가 조사를 진행한 뒤, 이곳에 리포트가 도착합니다.</p><div class="submission-summary">${img(referenceURL(r),r.title)}<div>${badge(r.status)}<h3>${h(r.title)}</h3><p>${modeLabel(r.mode)} · ${h(r.region||'지역 제한 없음')}</p><p class="mono" style="margin-top:10px;font-size:10px">${h(r.id)}</p></div></div><div class="receipt-status"><span class="row"><i class="pulse"></i>사진과 요청사항이 저장되었습니다.</span><span class="small">${dateText(r.createdAt)}</span></div><div class="submission-actions"><a class="btn btn-primary" href="#/report/${h(r.id)}">진행 상태 보기 ${icon('arrow')}</a><a class="btn btn-outline" href="#/studio/${h(r.id)}">운영자 화면에서 이어가기 ${icon('upRight')}</a></div><p class="submission-note">시연 안내 · 현재 브라우저에 접수했습니다. 스튜디오에서 조사 패키지를 내려받아 기존 Codex·geo-sleuth 흐름으로 조사할 수 있습니다.</p></section></div>`;}
function renderPending(r){return `<div class="container"><div class="page-top"><div class="breadcrumb"><a href="#/requests">내 리서치</a>${icon('chevron')}<span>${h(r.title)}</span></div></div><div class="pending-layout">${img(referenceURL(r),r.title,'pending-image')}<section class="pending-card"><div class="row between">${badge(r.status)}<span class="mono small muted">${h(r.id)}</span></div><h2>${h(r.title)}</h2><p>${STATUS[r.status].detail}</p><div class="progress-track">${['접수 완료','리서치 중','리포트 전달'].map((t,i)=>`<div class="${STATUS[r.status].step>i?'active':''}"><div class="progress-line"></div><p>0${i+1} ${t}</p></div>`).join('')}</div><div class="brief-body"><h3>나의 요청사항</h3><p>${h(r.brief)}</p></div><p>진행 상태는 운영자가 조사 단계에 맞춰 업데이트합니다.<br>리포트가 전달되면 이 페이지에서 확인할 수 있습니다.</p><div class="row row-wrap"><a class="btn btn-primary" href="#/studio/${h(r.id)}">스튜디오에서 조사 진행 ${icon('upRight')}</a><a class="btn btn-outline" href="#/requests">내 리서치로</a></div></section><div class="storage-note" style="margin-top:18px">${icon('info')}시제품에서는 모델을 자동 호출하지 않습니다. 운영자가 실제 조사 후 결과를 가져와야 리포트가 표시됩니다.</div></div></div>`;}
function renderStudio(r){
  if(r&&editingId!==r.id){editingId=r.id;editorReport=normalizeReport(r.draft||r.report||reportTemplate(r));studioTab='brief';}
  return `<div class="container studio"><div class="page-top"><div class="breadcrumb"><a href="#/">홈</a>${icon('chevron')}<span>운영자 스튜디오</span></div><div class="request-head"><div><div class="studio-title"><h1>리서치 스튜디오</h1><span class="label-tag">OPERATOR</span></div><p>기존 조사 흐름을 그대로, 완성된 결과를 리포트로 연결합니다.</p></div><a class="btn btn-outline btn-small" href="#/requests">의뢰 목록 ${icon('arrow')}</a></div></div><div class="notice">로컬 운영 화면입니다. 접수한 의뢰는 Codex·geo-sleuth가 자동 조사합니다. 조사 중인 의뢰는 고객 화면에서 실시간으로 확인하고, 완료 후 여기서 결과를 보완할 수 있습니다.</div><div class="studio-layout"><aside class="studio-queue"><div class="queue-header"><span>리서치 의뢰</span><span>${requests.length}</span></div>${requests.map(x=>`<a class="queue-item ${r?.id===x.id?'active':''}" href="#/studio/${h(x.id)}">${img(referenceURL(x),x.title)}<div><h3>${h(x.title)}</h3>${badge(x.status)}<span class="mono">${h(x.id)}</span></div></a>`).join('')}</aside>${r?`<section class="studio-panel"><div class="panel-top"><div class="row">${badge(r.status)}${sampleTag(r)}</div><h2>${h(r.title)}</h2><div class="row between"><span class="mono">${h(r.id)}</span><button class="text-button" data-action="export-backup" data-id="${h(r.id)}">의뢰 백업</button></div><div class="tabs" role="tablist" aria-label="운영자 작업 단계">${[['brief','의뢰 브리프'],['result','결과 작성'],['import','JSON 가져오기']].map(([key,label])=>`<button role="tab" aria-selected="${studioTab===key}" class="${studioTab===key?'active':''}" data-action="studio-tab" data-value="${key}">${label}</button>`).join('')}</div></div><div class="panel-content">${studioTab==='brief'?renderBrief(r):studioTab==='result'?renderEditor(r):renderImport(r)}</div></section>`:`<div class="empty-state">${icon('folder')}<h3>의뢰가 없습니다</h3><p>레퍼런스 사진으로 첫 의뢰를 만들어 보세요.</p><a class="btn btn-primary" href="#/new">새 리서치</a></div>`}</div></div>`;
}
function renderBrief(r){return `<div class="brief-block">${img(referenceURL(r),r.title,'',`data-action="zoom-reference" data-id="${h(r.id)}"`)}<dl class="brief-spec"><div><dt>리서치 유형</dt><dd>${modeLabel(r.mode)}</dd></div><div><dt>지역 조건</dt><dd>${h(r.region||'제한 없음')}</dd></div><div><dt>촬영 목적</dt><dd>${h(r.purpose)}</dd></div><div><dt>희망 촬영일</dt><dd>${h(r.date||'미정')}</dd></div><div><dt>접수일</dt><dd>${dateText(r.createdAt)}</dd></div><div><dt>추가 조건</dt><dd>${h(r.constraints||'없음')}</dd></div></dl></div><div class="brief-body"><h3>리서치 요청사항</h3><p>${h(r.brief)}</p></div><div class="operator-guide"><h3>${icon('compass')} 기존 조사 흐름으로 연결하기</h3><ol><li>조사 패키지 ZIP을 내려받아 폴더에 압축을 풉니다.</li><li>Codex에서 사진과 <code>TASK.md</code>를 열고 geo-sleuth로 조사합니다.</li><li><code>result.json</code>과 근거 이미지를 결과 작성 화면에서 가져옵니다.</li><li>미리보기를 확인한 뒤 리포트를 전달합니다.</li></ol><div class="row row-wrap"><button class="btn btn-primary btn-small" data-action="download-packet" data-id="${h(r.id)}">${icon('download')} 조사 패키지 ZIP</button><button class="btn btn-outline btn-small" data-action="copy-task" data-id="${h(r.id)}">${icon('copy')} 조사 요청 복사</button><button class="btn btn-outline btn-small" data-action="download-reference" data-id="${h(r.id)}">원본 사진</button></div><p class="small">원본 사진, 요청 JSON, TASK.md, 결과 템플릿이 포함됩니다. API 키가 필요하지 않습니다.</p></div><details><summary class="small muted" style="cursor:pointer;margin-bottom:10px">Codex에 전달할 조사 요청 보기</summary><pre class="code-block">${h(handoffText(r))}</pre></details><div class="status-actions"><button class="btn btn-primary btn-small" data-action="set-status" data-value="researching" data-id="${h(r.id)}">${icon('search')} 리서치 시작으로 변경</button><button class="btn btn-outline btn-small" data-action="studio-tab" data-value="result">결과 작성으로 이동 ${icon('arrow')}</button>${r.report?`<a class="btn btn-outline btn-small" href="#/report/${h(r.id)}">전달된 리포트 보기</a>`:''}</div>`;}
const textField=(name,label,value,placeholder='',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" value="${h(value??'')}" placeholder="${h(placeholder)}" ${extra}></label>`;
const textArea=(name,label,value,placeholder='',rows=3)=>`<label class="field"><span>${label}</span><textarea name="${name}" rows="${rows}" placeholder="${h(placeholder)}">${h(value??'')}</textarea></label>`;
function renderEditor(r){const e=editorReport;return `${r.isSample?'<div class="notice">샘플 의뢰입니다. 예시 데이터를 수정하거나 결과 가져오기 흐름을 시연할 수 있습니다. 샘플 표시는 계속 유지됩니다.</div>':''}<form id="result-form" novalidate><div id="result-error" role="alert"></div><section class="form-section"><div class="form-section-heading"><span>01</span><h2>리서치 결론</h2></div>${textField('title','리포트 제목',e.title,'예: 물가의 산책로에서 능선을 마주하는 자리','maxlength="200"')}${textField('place_name','장소명 / 확인된 지역 <em>*</em>',e.place_name,'확인된 범위까지만 입력하세요','maxlength="300"')}${textField('region','지역 표시',e.region,'예: 제주 · 대한민국','maxlength="200"')}${textArea('summary','리서치 요약 <em>*</em>',e.summary,'장소 판단과 확인 근거를 요약해 주세요.')}</section><section class="form-section"><div class="form-section-heading"><span>02</span><h2>카메라 위치와 방향</h2></div><label class="field"><span>좌표 유형</span><select name="coordinate_type">${[['unknown','유형 미확인'],['camera','확인된 카메라 위치'],['camera_estimate','추정 촬영 위치'],['landmark','장소 대표 좌표'],['region','지역 참고 좌표']].map(([v,l])=>`<option value="${v}" ${e.coordinate_type===v?'selected':''}>${l}</option>`).join('')}</select></label><div class="field-grid">${textField('lat','위도 · WGS84',e.lat,'예: 33.45','type="number" step="any" min="-90" max="90"')}${textField('lon','경도 · WGS84',e.lon,'예: 126.92','type="number" step="any" min="-180" max="180"')}</div><div class="field-grid">${textField('radius_m','오차 반경 · m',e.radius_m,'미확정 시 비워 두세요','type="number" step="any" min="0"')}${textField('heading','촬영 방향 · °',e.heading,'북 0° / 동 90° / 남 180°','type="number" step="any"')}</div><label class="field"><span>판단 신뢰도 <small>확률이 아닌 조사 등급입니다</small></span><select name="confidence">${[['unrated','미평가'],['high','높음 · 독립적인 근거가 일치'],['medium','중간 · 일부 근거 일치, 추가 확인 필요'],['low','낮음 · 가설 수준']].map(([v,l])=>`<option value="${v}" ${e.confidence===v?'selected':''}>${l}</option>`).join('')}</select></label><p class="field-hint">좌표를 확정하지 못했으면 비워 두고 ‘추가 확인 필요’로 전달합니다. 장소 대표점과 카메라 위치를 구분해 주세요.</p></section><section class="form-section"><div class="form-section-heading"><span>03</span><h2>조사 근거와 이미지</h2></div>${textArea('clues_text','판단 근거 <small>한 줄에 하나, 제목 | 설명</small>',e.clues.map(x=>x.title+(x.description?' | '+x.description:'')).join('\n'),'산 능선 | DEM 윤곽과 사진 속 능선이 일치합니다.') }<div class="row between"><span class="small muted">근거 이미지 · JPG / PNG / WEBP</span><button class="btn btn-outline btn-small" type="button" data-action="add-evidence">${icon('plus')} 이미지 추가</button></div><div class="evidence-upload-grid">${e.evidence.map((x,i)=>`<div class="evidence-upload">${imageURL(x.dataUrl||x.url)?img(x.dataUrl||x.url,x.name):`<div class="no-image" style="height:105px;min-height:0">${icon('image')}</div>`}<span class="evidence-name" title="${h(x.name)}">${h(x.name)}${!imageURL(x.dataUrl||x.url)?' · 파일 연결 필요':''}</span><button type="button" data-action="remove-evidence" data-index="${i}" aria-label="${h(x.name)} 근거 이미지 삭제">✕</button></div>`).join('')}</div><input id="evidence-files" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden>${textArea('sources_text','출처 <small>한 줄에 하나, 제목 | URL</small>',e.sources.map(x=>x.title+' | '+x.url).join('\n'),'공식 관광 안내 | https://example.com')}</section><section class="form-section"><div class="form-section-heading"><span>04</span><h2>촬영 준비와 확인할 점</h2></div>${textArea('composition','추천 구도',e.composition,'확인된 구도와 배치만 작성해 주세요.',2)}${textArea('best_time','빛과 시간대',e.best_time,'일조·날씨 미확인 시 비워 두세요.',2)}${textArea('access','접근과 현장 확인',e.access,'실제 확인한 동선과 촬영 접근성을 작성해 주세요.',2)}${textField('lens','화각·렌즈 참고',e.lens,'미확인 시 비워 두세요')}${textArea('caveats_text','남은 확인사항 <small>한 줄에 하나</small>',e.caveats.join('\n'),'현장 출입 가능 여부는 확인하지 못했습니다.',3)}${textArea('alternatives_text','다른 후보 <small>한 줄에 하나, 후보명 | 이유</small>',e.alternatives.map(x=>x.name+' | '+x.reason).join('\n'),'후보 장소 | 구분을 위해 확인할 내용',2)}</section><div class="publish-bar"><div><button class="text-button" type="button" data-action="save-draft">임시 저장</button><p style="margin-top:5px">자동으로 고객에게 전달되지 않습니다.</p></div><div class="row"><button class="btn btn-outline btn-small" type="button" data-action="preview-report">미리보기</button><button class="btn btn-outline btn-small" type="button" data-action="publish-review">추가 확인 필요</button><button class="btn btn-primary btn-small" type="submit">리포트 전달 ${icon('arrow')}</button></div></div></form>`;}
function renderImport(r){return `<div class="import-box">${icon('file')}<h3>조사 결과 JSON을 가져오세요</h3><p>기존 geo-sleuth 결과의 좌표·방향·대안 등을 읽습니다.<br>파일에 없는 정보는 결과 작성 화면에서 보완할 수 있습니다.</p><button class="btn btn-primary btn-small" data-action="select-result-json">${icon('upload')} result.json 선택</button><input type="file" id="result-json-file" accept="application/json,.json" hidden></div><div id="import-error" role="alert"></div><label class="import-label" for="json-editor">또는 JSON을 붙여 넣으세요</label><textarea id="json-editor" class="import-editor" spellcheck="false" aria-label="조사 결과 JSON">${h(json(reportTemplate(r)))}</textarea><div class="row between" style="margin-top:14px"><button class="text-button" data-action="download-template" data-id="${h(r.id)}">결과 템플릿 다운로드</button><button class="btn btn-primary btn-small" data-action="apply-json">결과 작성에 적용 ${icon('arrow')}</button></div><p class="admin-note">필드: place_name, summary, lat, lon, radius_m, heading, confidence, clues, evidence, sources, caveats. 근거 이미지의 로컬 파일 경로는 업로드 후 연결합니다. JSON을 가져오는 것만으로 리포트가 전달되지는 않습니다.</p>`;}
function confidenceText(c){return {high:'높음',medium:'중간',low:'낮음',unrated:'미평가'}[c]||'미평가';}
function compass(heading){if(!Number.isFinite(heading))return '<div class="direction-unknown">방향<br>미산정</div>';const deg=Number.isFinite(heading)?heading:0;return `<svg class="compass" viewBox="0 0 100 100" aria-label="${heading===null?'방향 미확정':h(heading)+'도 촬영 방향'}"><circle cx="50" cy="50" r="37" fill="#f8faf1" stroke="#c8d4b6" stroke-dasharray="2 4"/><path d="M50 9v7m0 68v7M9 50h7m68 0h7" stroke="#a5b790"/><text x="50" y="9" text-anchor="middle" font-size="8" fill="#799063" font-family="Arial">N</text><g transform="rotate(${deg} 50 50)"><path d="m50 50-19-28a34 34 0 0 1 38 0Z" fill="#b7d78377"/><path d="M50 50V21m0 0-4 7m4-7 4 7" stroke="#5b7c3e" stroke-width="1.5" fill="none"/></g><circle cx="50" cy="50" r="3" fill="#5b7c3e"/></svg>`;}
function renderReport(r,preview=false){
  const e=preview?r.draft:r.report;if(!e)return renderPending(r);
  const validCoord=Number.isFinite(e.lat)&&Number.isFinite(e.lon);
  const mapURL=validCoord?`https://www.openstreetmap.org/?mlat=${e.lat}&mlon=${e.lon}#map=16/${e.lat}/${e.lon}`:'';
  const pad=validCoord?Math.max(.004,(e.radius_m||100)/65000):.004;
  const mapEmbed=validCoord?`https://www.openstreetmap.org/export/embed.html?bbox=${Math.max(-180,e.lon-pad)}%2C${Math.max(-90,e.lat-pad)}%2C${Math.min(180,e.lon+pad)}%2C${Math.min(90,e.lat+pad)}&layer=mapnik&marker=${e.lat}%2C${e.lon}`:'';
  const visibleEvidence=e.evidence.filter(x=>imageURL(x.dataUrl||x.url));
  return `<article class="container report"><div class="print-brand">FRAME / LOCATION RESEARCH</div><div class="page-top"><div class="breadcrumb"><a href="#/requests">내 리서치</a>${icon('chevron')}<span>촬영지 리포트</span></div></div>${preview?`<div class="report-preview-note">임시 저장된 결과의 미리보기입니다. 아직 고객용 리포트에 반영되지 않았습니다. <a class="text-button" href="#/studio/${h(r.id)}">스튜디오로 돌아가기</a></div>`:''}<div class="report-top"><div><div class="eyebrow"><span class="dot"></span> LOCATION FIELDNOTES <span class="mono" style="letter-spacing:0;margin-left:4px">${h(r.id)}</span></div><h1>${h(e.title||r.title)}</h1></div><div class="row"><button class="btn btn-outline btn-small" data-action="print-report">${icon('print')} PDF로 저장</button><button class="btn btn-outline btn-small" data-action="export-report" data-id="${h(r.id)}" data-preview="${preview}">${icon('download')} 결과 JSON</button><button class="btn btn-primary btn-small" data-action="export-backup" data-id="${h(r.id)}">${icon('folder')} 의뢰 백업</button></div></div>${r.isSample?`<div class="sample-banner">${icon('info')}시연용 리포트입니다. 사진·좌표·방향·판단 내용은 화면 구성을 위한 예시이며 실제 조사 결과가 아닙니다.</div>`:''}<section class="report-hero"><div class="report-main-photo" data-action="zoom-reference" data-id="${h(r.id)}">${img(referenceURL(r),'조사에 사용한 레퍼런스 사진')}<div class="image-caption"><span>ORIGINAL REFERENCE · ${h(r.reference.name)}</span>${icon('frame')}</div></div><div class="report-place"><div class="eyebrow">${r.isSample?'ILLUSTRATIVE LOCATION':'RESEARCHED LOCATION'}</div><h2>${h(e.place_name||'위치 확인 중')}</h2><p class="place-region">${h(e.region||'지역 정보 미등록')}</p><div class="line"></div><div class="coordinate-block"><div><span>${({camera:'CAMERA POSITION',camera_estimate:'ESTIMATED CAMERA POSITION',landmark:'LANDMARK REFERENCE',region:'REGION REFERENCE',unknown:'REFERENCE COORDINATES'})[e.coordinate_type]||'REFERENCE COORDINATES'} / WGS84</span><b>${validCoord?`${e.lat.toFixed(5)}°, ${e.lon.toFixed(5)}°`:'좌표 미확정'}</b></div>${validCoord?`<button class="icon-button" data-action="copy-coordinates" data-id="${h(r.id)}" data-preview="${preview}" aria-label="좌표 복사">${icon('copy')}</button>`:''}</div><div class="spec-row"><div class="mini-spec"><span>추정 오차 반경</span><strong>${e.radius_m!==null&&e.radius_m!==undefined?'± '+h(e.radius_m):'미확정'}${e.radius_m!==null&&e.radius_m!==undefined?'<small>m</small>':''}</strong></div><div class="mini-spec"><span>촬영 방향</span><strong>${e.heading!==null&&e.heading!==undefined?h(e.heading)+'°':'미확정'}</strong></div><div class="mini-spec"><span>판단 신뢰도</span><strong class="confidence">${confidenceText(e.confidence)}</strong></div><div class="mini-spec"><span>의뢰 유형</span><strong style="font-size:11px">${r.mode==='alternative'?'대체 촬영지':'원본 촬영지'}</strong></div></div><p class="small">${r.isSample?'수치는 시연용입니다. 실제 촬영 위치를 확정하지 않습니다.':'신뢰도는 조사 등급이며 통계적 정답 확률이 아닙니다. 오차 범위와 미확인 사항을 함께 확인해 주세요.'}</p>${validCoord?`<a class="btn btn-outline btn-block" href="${h(mapURL)}" target="_blank" rel="noopener noreferrer">지도에서 위치 열기 ${icon('upRight')}</a>`:''}</div></section><nav class="report-nav" aria-label="리포트 내 이동"><a href="#summary" data-action="report-anchor" data-target="summary">리서치 요약</a><a href="#evidence" data-action="report-anchor" data-target="evidence">확인 근거</a><a href="#shooting" data-action="report-anchor" data-target="shooting">촬영 준비</a></nav><div class="report-body"><div class="report-column">${researchDetails(e)}<section class="report-section" id="summary"><div class="report-section-title"><span>01</span><h2>이 장면을 찾은 과정</h2></div><p class="report-summary">${h(e.summary||'요약이 등록되지 않았습니다.')}</p>${e.clues.length?`<div class="clue-list">${e.clues.map((x,i)=>`<div class="clue-row"><span class="clue-letter">${String.fromCharCode(65+i%26)}</span><div><h3>${h(x.title)}<span class="label-tag">${h(x.kind||'조사 근거')}</span></h3><p>${h(x.description)}</p></div></div>`).join('')}</div>`:''}</section><section class="report-section" id="evidence"><div class="report-section-title"><span>02</span><h2>사진과 대조한 근거</h2></div>${visibleEvidence.length?visibleEvidence.map((x,i)=>`<figure class="evidence-figure"><div class="evidence-visual" data-action="zoom-evidence" data-id="${h(r.id)}" data-index="${i}" data-preview="${preview}">${img(x.dataUrl||x.url,x.name)}${r.isSample&&x.annotated?'<svg class="annotation-overlay" viewBox="0 0 700 400" preserveAspectRatio="none"><path d="M220 180 300 110 360 160 430 95 470 130 560 73 640 150" fill="none" stroke="#e2ef9b" stroke-width="2" stroke-dasharray="4 4"/><path d="M80 287 260 275 460 290 670 265" fill="none" stroke="#e2ef9b" stroke-width="1.5"/></svg><div class="annotation-tag annot-a"><b>A</b><span>RIDGELINE</span></div><div class="annotation-tag annot-b"><b>B</b><span>WATERFRONT</span></div>':''}</div><figcaption><h3>${h(x.name)}</h3>${x.description?`<p>${h(x.description)}</p>`:''}</figcaption></figure>`).join(''):'<div class="notice">근거 이미지가 아직 등록되지 않았습니다. 아래 출처와 리서치 요약에서 확인 가능한 범위를 살펴보세요.</div>'}${e.alternatives.length?`<div class="clue-list">${e.alternatives.map(x=>`<div class="clue-row"><span class="clue-letter">↗</span><div><h3>다른 후보 · ${h(x.name)}</h3><p>${h(x.reason)}</p></div></div>`).join('')}</div>`:''}</section></div><aside class="report-side"><section class="report-section"><div class="report-section-title"><span>↗</span><h2>카메라가 향하는 곳</h2></div><div class="map-card">${validCoord?`<iframe src="${h(mapEmbed)}" title="${h(e.place_name)} 위치 지도" loading="lazy" referrerpolicy="no-referrer"></iframe>`:'<div class="map-placeholder">좌표가 확정되면 지도를 표시합니다.</div>'}<div class="map-footer"><span>© OpenStreetMap contributors</span>${validCoord?`<a href="${h(mapURL)}" target="_blank" rel="noopener noreferrer">큰 지도 ${icon('external')}</a>`:''}</div></div><div class="camera-card">${compass(e.heading)}<div><h3>${e.heading!==null&&e.heading!==undefined?h(e.heading)+'° 방향의 시야':'방향 미확정'}</h3><p>북쪽을 0°로, 시계방향으로 표시합니다.<br>${r.isSample?'시연용 방향 예시입니다.':'실제 촬영 전 주변 지형과 함께 확인하세요.'}</p></div></div></section><section class="report-section" id="shooting"><div class="report-section-title"><span>03</span><h2>다음 촬영을 위한 메모</h2></div><div class="shooting-list">${[['camera','구도와 프레이밍',e.composition],['sun','빛과 시간대',e.best_time],['walk','접근과 현장 확인',e.access],['frame','화각·렌즈 참고',e.lens]].map(([ic,title,value])=>`<div class="shooting-item"><h3>${icon(ic)}${title}</h3><p>${h(value||'아직 확인하지 않은 항목입니다.')}</p></div>`).join('')}</div><div class="caveat-box"><h3>${icon('info')} 방문 전 확인해 주세요</h3><ul>${(e.caveats.length?e.caveats:['출입·촬영 허가와 현재 현장 상태는 방문 전 별도로 확인해 주세요.']).map(x=>`<li>${h(x)}</li>`).join('')}</ul></div><div class="sources"><h3>확인 자료와 출처</h3>${e.sources.length?e.sources.filter(x=>safeURL(x.url)).map(x=>`<a href="${h(safeURL(x.url))}" target="_blank" rel="noopener noreferrer">${h(x.title||x.url)} ${icon('external')}</a>`).join(''):'<p class="small muted">등록된 출처가 없습니다.</p>'}</div></section></aside></div><div class="report-note"><span>FRAME LOCATION RESEARCH · ${dateText(r.updatedAt||r.createdAt)}</span><span>${r.isSample?'시연용 예시 · 실제 조사 결과 아님':'위치·방향은 등록된 조사 결과를 기준으로 표시합니다.'}</span></div><div class="report-bottom-cta"><div><h3>또 다른 장면이 떠올랐나요?</h3><p>다음 레퍼런스도 FRAME에 남겨 보세요.</p></div><a class="btn btn-primary" href="#/new">새로운 촬영지 찾기 ${icon('arrow')}</a></div></article>`;
}
function routeInfo(){const hash=location.hash.slice(1)||'/';const [path,query='']=hash.split('?');return {path,params:new URLSearchParams(query),segments:path.split('/').filter(Boolean)};}
async function render(scroll=true){
  disposeLive?.();disposeLive=null;
  requests=await allRequests();const {path,segments,params}=routeInfo();currentRoute=path;chrome(path);
  const request=requests.find(r=>r.id===segments[1]);
  if(path==='/')main.innerHTML=renderHome();
  else if(segments[0]==='new'){main.innerHTML=renderNew();bindUpload();if(window.__framePrefill){const p=window.__framePrefill;const f=document.querySelector('#request-form');for(const [k,v]of Object.entries(p)){const field=f.elements.namedItem(k);if(field)field.value=v;}window.__framePrefill=null;}}
  else if(segments[0]==='requests')main.innerHTML=renderRequests();
  else if(segments[0]==='submitted'&&request)main.innerHTML=renderSubmitted(request);
  else if(segments[0]==='studio')main.innerHTML=renderStudio(request||requests[0]);
  else if(segments[0]==='live'&&request)main.innerHTML=renderLive(request);
  else if(segments[0]==='report'&&request)main.innerHTML=request.job&&!request.report?renderLive(request):renderReport(request,params.get('preview')==='1');
  else main.innerHTML=`<div class="container" style="padding-top:60px;padding-bottom:80px"><div class="empty-state">${icon('folder')}<h3>이 리서치를 찾을 수 없습니다</h3><p>이 로컬 서버에 저장된 의뢰인지 확인해 주세요.</p><a class="btn btn-primary" href="#/requests">내 리서치로 이동</a></div></div>`;
  if(segments[0]==='studio'&&studioTab!=='brief'){
    const selected=selectedStudioRequest();
    if(selected?.isSample&&selected.reference.url==='./assets/lake.jpg')document.querySelector('.panel-content')?.insertAdjacentHTML('afterbegin','<div class="notice row between row-wrap"><span>호수 샘플 의뢰의 결과 전달을 빠르게 시연할 수 있습니다.</span><button class="btn btn-outline btn-small" data-action="fill-demo-result">샘플 결과 채우기</button></div>');
  }
  document.title=(segments[0]==='studio'?'리서치 스튜디오':segments[0]==='new'?'리서치 의뢰':segments[0]==='report'&&request?request.report?.title||request.title:segments[0]==='requests'?'내 리서치':segments[0]==='live'?'실시간 리서치':'사진에서 시작하는 촬영지 리서치')+' — FRAME';
  if(document.querySelector('.live-page'))disposeLive=mountLive(request,{onError:message=>toast(message,true)});
  if(segments[0]==='new')mountRuntime();
  if(segments[0]==='report'&&request?.job&&request.report)document.querySelector('.report-top')?.insertAdjacentHTML('afterend',`<div class="live-report-return"><a href="#/live/${h(request.id)}">← 조사 과정과 실행 기록 보기</a><span>${request.job.model?h(modelLabel(request.job.model))+' · '+h(request.job.reasoningEffort||''):'Codex · geo-sleuth 자동 조사'}</span></div>`);
  if(scroll)window.scrollTo({top:0,behavior:'instant'});
}
function showInline(id,error){const el=document.querySelector('#'+id);if(el){el.innerHTML=`<div class="error-box">${h(error.message||error)}</div>`;el.scrollIntoView({behavior:'smooth',block:'center'});}else toast(error.message||String(error),true);}
function bindUpload(){const zone=document.querySelector('#upload-zone');if(!zone)return;zone.addEventListener('click',e=>{if(!e.target.closest('[data-action]'))document.querySelector('#reference-file').click();});zone.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target===zone){e.preventDefault();document.querySelector('#reference-file').click();}});for(const name of ['dragenter','dragover'])zone.addEventListener(name,e=>{e.preventDefault();zone.classList.add('is-drag');});for(const name of ['dragleave','drop'])zone.addEventListener(name,e=>{e.preventDefault();zone.classList.remove('is-drag');});zone.addEventListener('drop',async e=>{try{if(e.dataTransfer.files.length)await setReference(e.dataTransfer.files[0]);}catch(err){toast(err.message,true);}});}
async function readPhoto(file,maxMB=20){
  if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('JPG, PNG, WEBP 사진 파일을 선택해 주세요.');
  if(file.size>maxMB*1024*1024)throw new Error(`사진은 ${maxMB}MB 이하로 올려 주세요.`);
  const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('사진을 읽지 못했습니다.'));reader.readAsDataURL(file);});
  await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{if(!im.naturalWidth)reject(new Error('올바른 사진 파일이 아닙니다.'));else resolve();};im.onerror=()=>reject(new Error('손상되었거나 브라우저에서 열 수 없는 사진입니다.'));im.src=dataUrl;});
  return {name:file.name,type:file.type,dataUrl};
}
async function setReference(file){pendingReference=await readPhoto(file);document.querySelector('#upload-area').innerHTML=uploadMarkup();bindUpload();}
function download(content,name,type='application/json'){const blob=content instanceof Blob?content:new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
async function referenceBlob(r){const src=referenceURL(r);if(!src)throw new Error('레퍼런스 사진이 없습니다.');const response=await fetch(src);if(!response.ok)throw new Error('사진 파일을 읽을 수 없습니다.');return response.blob();}
async function portableRequest(r){
  const copy=structuredClone(r);
  for(const report of [copy.report,copy.draft].filter(Boolean))if(report.map_image?.url?.startsWith('/api/')){
    const response=await fetch(report.map_image.url);if(!response.ok)throw new Error('백업할 지도 이미지를 읽지 못했습니다.');
    const blob=await response.blob();report.map_image.url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});
  }
  for(const report of [copy.report,copy.draft].filter(Boolean))for(const evidence of report.evidence||[]){
    const src=evidence.dataUrl||evidence.url;
    if(src?.startsWith('/api/')){
      const response=await fetch(src);if(!response.ok)throw new Error('백업할 근거 이미지를 읽지 못했습니다.');
      const blob=await response.blob();evidence.dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});delete evidence.url;
    }
  }
  return copy;
}
function extension(type){return {'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[type]||'jpg';}
async function copyText(value){try{await navigator.clipboard.writeText(value);}catch{const ta=document.createElement('textarea');ta.value=value;ta.style.position='fixed';ta.style.opacity='0';document.body.append(ta);ta.select();const ok=document.execCommand('copy');ta.remove();if(!ok)throw new Error('클립보드 접근이 차단되었습니다. 파일 다운로드를 사용해 주세요.');}}
function selectedStudioRequest(){return requests.find(r=>r.id===editingId);}
function collectEditor(){
  const form=document.querySelector('#result-form');if(!form)return editorReport;
  const f=new FormData(form);const lines=name=>String(f.get(name)||'').split('\n').map(x=>x.trim()).filter(Boolean);
  const pairs=name=>lines(name).map(line=>{const i=line.indexOf('|');return i===-1?[line,'']:[line.slice(0,i).trim(),line.slice(i+1).trim()];});
  return normalizeReport({...editorReport,...Object.fromEntries(f.entries()),clues:pairs('clues_text').map(([title,description])=>({title,description,kind:'조사 근거'})),sources:pairs('sources_text').map(([title,url])=>({title:url?title:'확인 출처',url:url||title})),caveats:lines('caveats_text'),alternatives:pairs('alternatives_text').map(([name,reason])=>({name,reason}))});
}
async function persistDraft(){editorReport=collectEditor();const r=selectedStudioRequest();r.draft=structuredClone(editorReport);r.updatedAt=new Date().toISOString();await saveRequest(r);return r;}
async function publish(review=false){try{editorReport=collectEditor();validatePublication(editorReport,review);if(!review&&!editorReport.evidence.some(x=>imageURL(x.dataUrl||x.url)))throw new Error('리포트를 완성하려면 실제 근거 이미지를 한 장 이상 추가해 주세요. 이미지 없이 확인된 범위만 전달하려면 ‘추가 확인 필요’를 사용하세요.');const r=selectedStudioRequest();r.report=structuredClone(editorReport);r.draft=null;r.status=review?'review':'ready';r.updatedAt=new Date().toISOString();await saveRequest(r);toast(review?'확인된 범위와 남은 사항을 전달했습니다.':'촬영지 리포트가 전달되었습니다.');go('/report/'+r.id);}catch(error){showInline('result-error',error);}}
async function confirmAction(title,body){return new Promise(resolve=>{const d=document.querySelector('#confirm-dialog');document.querySelector('#confirm-content').innerHTML=`<h2>${h(title)}</h2><p>${h(body)}</p><div class="row"><button class="btn btn-outline" data-confirm="no">취소</button><button class="btn btn-primary" data-confirm="yes">계속</button></div>`;const onClick=e=>{const b=e.target.closest('[data-confirm]');if(b){finish(b.dataset.confirm==='yes');}};const onCancel=e=>{e.preventDefault();finish(false);};function finish(result){d.close();d.removeEventListener('click',onClick);d.removeEventListener('cancel',onCancel);resolve(result);}d.addEventListener('click',onClick);d.addEventListener('cancel',onCancel);d.showModal();});}
function openLightbox(src,caption){if(!imageURL(src))return;const d=document.querySelector('#lightbox');d.querySelector('img').src=src;d.querySelector('img').alt=caption;d.querySelector('p').textContent=caption;d.showModal();}
async function applyJSON(text){try{const raw=JSON.parse(text);if(raw.request_id&&raw.request_id!==editingId)throw new Error(`다른 의뢰(${raw.request_id})의 결과입니다. 해당 의뢰를 선택한 뒤 가져와 주세요.`);const parsed=normalizeReport(raw);editorReport={...parsed,evidence:parsed.evidence.map(x=>{const existing=editorReport?.evidence.find(y=>x.file&&y.file===x.file);return existing&&!x.dataUrl?{...x,dataUrl:existing.dataUrl||existing.url}:x;})};studioTab='result';await render(false);toast('JSON을 적용했습니다. 근거 이미지와 내용을 확인해 주세요.');}catch(err){showInline('import-error',err instanceof SyntaxError?new Error('JSON 문법을 확인해 주세요. 쉼표·따옴표·괄호를 점검해 주세요.'):err);}}
document.addEventListener('submit',async event=>{
  if(event.target.id==='request-form'){
    event.preventDefault();if(creating)return;const f=event.target;const button=f.querySelector('[type="submit"]');
    try{if(!pendingReference)throw new Error('레퍼런스 사진을 먼저 올려 주세요.');const data=Object.fromEntries(new FormData(f).entries());if(!data.title.trim()||!data.brief.trim())throw new Error('프로젝트 이름과 리서치 요청사항을 입력해 주세요.');creating=true;button.disabled=true;const r={id:newId(),...data,title:data.title.trim(),brief:data.brief.trim(),region:data.region.trim()||'지역 제한 없음',reference:structuredClone(pendingReference),status:'received',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),isSample:!!pendingReference.isSample,report:null};const created=await createRequest(r);pendingReference=null;go('/live/'+created.id);}catch(error){showInline('request-error',error);}finally{creating=false;button.disabled=false;}
  }else if(event.target.id==='result-form'){event.preventDefault();await publish(false);}
});
document.addEventListener('change',async event=>{
  const file=event.target.files?.[0];if(!file)return;
  try{
    if(event.target.id==='reference-file')await setReference(file);
    else if(event.target.id==='result-json-file'){if(file.size>10*1024*1024)throw new Error('결과 JSON은 10MB 이하로 가져와 주세요.');await applyJSON(await file.text());}
    else if(event.target.id==='evidence-files'){
      editorReport=collectEditor();const files=[...event.target.files];if(editorReport.evidence.length+files.length>15)throw new Error('근거 이미지는 최대 15장까지 추가할 수 있습니다.');
      const photos=await Promise.all(files.map(f=>readPhoto(f,10)));
      for(const p of photos){const existing=editorReport.evidence.find(x=>x.file?.split(/[\\/]/).pop()===p.name||x.name===p.name);if(existing){existing.dataUrl=p.dataUrl;existing.file=p.name;}else editorReport.evidence.push({name:p.name,description:'',dataUrl:p.dataUrl,file:p.name});}
      await render(false);toast(`${photos.length}장의 근거 이미지를 연결했습니다.`);
    }else if(event.target.id==='backup-file'){
      if(file.size>150*1024*1024)throw new Error('백업 파일은 150MB 이하로 가져와 주세요.');const r=restoreRequest(JSON.parse(await file.text()));
      if(requests.some(x=>x.id===r.id)&&!await confirmAction('같은 의뢰가 이미 있습니다','가져온 백업 내용으로 이 브라우저의 의뢰를 교체할까요?'))return;
      await saveRequest(r);toast('의뢰와 사진을 가져왔습니다.');if(location.hash==='#/requests')await render(false);else go('/requests');
    }
  }catch(error){toast(error instanceof SyntaxError?'올바른 JSON 파일을 선택해 주세요.':error.message,true);}finally{event.target.value='';}
});
document.addEventListener('click',async event=>{
  const target=event.target.closest('[data-action]');if(!target)return;event.preventDefault();const action=target.dataset.action;const r=requests.find(x=>x.id===target.dataset.id)||selectedStudioRequest();
  try{
    if(action==='refresh-runtime')await mountRuntime();
    else if(action==='skip-main'){main.focus();main.scrollIntoView({behavior:'smooth'});}
    else if(action==='sample-report')go('/report/'+SAMPLE_ID);
    else if(action==='sample-new'){const kind=target.dataset.kind;pendingReference={name:kind+'-reference.jpg',type:'image/jpeg',url:'./assets/'+kind+'.jpg',isSample:true};window.__framePrefill={title:kind==='coast'?'파도를 마주하는 촬영지':'산 능선이 겹치는 촬영지',mode:kind==='coast'?'alternative':'original',brief:kind==='coast'?'레퍼런스처럼 넓은 바다와 파도를 담을 수 있는 비슷한 촬영지를 찾아 주세요.':'사진 속 산과 능선이 보이는 실제 장소와 촬영 방향을 찾아 주세요.'};go('/new');}
    else if(action==='sample-reference'){pendingReference={name:'lake-reference.jpg',type:'image/jpeg',url:'./assets/lake.jpg',isSample:true};document.querySelector('#upload-area').innerHTML=uploadMarkup();bindUpload();const f=document.querySelector('#request-form');if(!f.elements.title.value)f.elements.title.value='호수와 능선이 겹치는 프레임';if(!f.elements.brief.value)f.elements.brief.value='사진 속 호수와 산 능선이 보이는 장소를 찾고, 카메라 위치와 방향을 근거와 함께 정리해 주세요.';toast('샘플 사진을 준비했습니다. 의뢰하기를 눌러 이어가세요.');}
    else if(action==='replace-image')document.querySelector('#reference-file').click();
    else if(action==='remove-reference'){pendingReference=null;document.querySelector('#upload-area').innerHTML=uploadMarkup();bindUpload();}
    else if(action==='filter'){filter=target.dataset.value;await render(false);}
    else if(action==='open-request')go('/report/'+r.id);
    else if(action==='restore-backup')document.querySelector('#backup-file').click();
    else if(action==='export-backup'){download(json({format:'frame-request-v1',exportedAt:new Date().toISOString(),request:await portableRequest(r)}),r.id+'.frame.json');toast('사진과 근거 이미지를 포함한 의뢰 백업을 내려받았습니다.');}
    else if(action==='delete-request'){if(await confirmAction('이 의뢰를 삭제할까요?','의뢰 목록에서 삭제합니다. 진행 중인 조사는 먼저 중지해 주세요. 필요하면 백업을 내려받으세요.')){await removeRequest(r.id);toast('의뢰를 삭제했습니다.');await render(false);}}
    else if(action==='studio-tab'){if(document.querySelector('#result-form'))editorReport=collectEditor();studioTab=target.dataset.value;await render(false);}
    else if(action==='copy-task'){await copyText(handoffText(r));toast('Codex에 전달할 조사 요청을 복사했습니다.');}
    else if(action==='download-reference')download(await referenceBlob(r),'reference.'+extension(r.reference.type));
    else if(action==='download-template')download(json(reportTemplate(r)),'result.template.json');
    else if(action==='download-packet'){
      const blob=await referenceBlob(r);const request={...r,reference:{name:'reference.'+extension(r.reference.type),type:r.reference.type}};delete request.report;delete request.draft;
      const folder=r.id+'/';const zip=zipBytes([{name:folder+'TASK.md',content:handoffText(r)},{name:folder+'request.json',content:json(request)},{name:folder+'result.template.json',content:json(reportTemplate(r))},{name:folder+'reference.'+extension(r.reference.type),content:new Uint8Array(await blob.arrayBuffer())}]);download(zip,r.id+'-research.zip');toast('사진과 조사 지침을 담은 패키지를 내려받았습니다.');
    }
    else if(action==='set-status'){r.status=target.dataset.value;r.updatedAt=new Date().toISOString();await saveRequest(r);toast('리서치 중으로 변경했습니다.');await render(false);}
    else if(action==='select-result-json')document.querySelector('#result-json-file').click();
    else if(action==='apply-json')await applyJSON(document.querySelector('#json-editor').value);
    else if(action==='fill-demo-result'){if(!r.isSample||r.reference.url!=='./assets/lake.jpg')throw new Error('호수 샘플 의뢰에서만 예시 결과를 사용할 수 있습니다.');editorReport=structuredClone(SAMPLE_REPORT);studioTab='result';await render(false);toast('시연용 결과를 채웠습니다. 미리보기 후 전달할 수 있습니다.');}
    else if(action==='add-evidence')document.querySelector('#evidence-files').click();
    else if(action==='remove-evidence'){editorReport=collectEditor();editorReport.evidence.splice(Number(target.dataset.index),1);await render(false);}
    else if(action==='save-draft'){await persistDraft();toast('결과를 임시 저장했습니다.');}
    else if(action==='preview-report'){const saved=await persistDraft();go('/report/'+saved.id+'?preview=1');}
    else if(action==='publish-review')await publish(true);
    else if(action==='print-report')window.print();
    else if(action==='export-report'){const report=target.dataset.preview==='true'?r.draft:r.report;const exported={...report,request_id:r.id,evidence:report.evidence.map(({dataUrl,url,...x})=>x)};download(json(exported),r.id+'-result.json');toast('결과 JSON을 내려받았습니다. 사진까지 보관하려면 의뢰 백업을 사용하세요.');}
    else if(action==='copy-coordinates'){const report=target.dataset.preview==='true'?r.draft:r.report;await copyText(`${report.lat}, ${report.lon}`);toast('WGS84 좌표를 복사했습니다.');}
    else if(action==='zoom-reference')openLightbox(referenceURL(r),r.reference.name);
    else if(action==='zoom-evidence'){const report=target.dataset.preview==='true'?r.draft:r.report;const e=report.evidence.filter(x=>imageURL(x.dataUrl||x.url))[Number(target.dataset.index)];if(e)openLightbox(e.dataUrl||e.url,e.name);}
    else if(action==='report-anchor')document.getElementById(target.dataset.target)?.scrollIntoView({behavior:'smooth'});
  }catch(error){toast(error.message||'작업을 완료하지 못했습니다.',true);}
});
document.querySelector('.lightbox-close').addEventListener('click',()=>document.querySelector('#lightbox').close());
document.querySelector('#lightbox').addEventListener('click',e=>{if(e.target.id==='lightbox')e.target.close();});
window.addEventListener('hashchange',()=>render().catch(e=>toast(e.message,true)));
window.addEventListener('unhandledrejection',event=>{console.error(event.reason);toast(event.reason?.message||'오류가 발생했습니다. 잠시 후 다시 시도해 주세요.',true);});
try{
  const existing=await allRequests();if(!existing.some(r=>r.id===SAMPLE_ID))await saveRequest(sampleRequest());
  await render();
}catch(error){main.innerHTML=`<div class="container" style="padding-top:60px"><div class="error-box">${h(error.message)}<br>npm run dev로 로컬 서버를 실행했는지 확인해 주세요.</div></div>`;}
